sketch.css:
.pb{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:10px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.pb *{box-sizing:border-box}
.strip{display:flex;gap:6px}
.bench{flex:1;display:flex;align-items:baseline;gap:6px;padding:6px 10px;border-radius:8px;background:var(--background);white-space:nowrap;overflow:hidden}
.bench .bn{color:var(--muted);font-size:11.5px;font-weight:500}
.bench .bp{font-weight:700;font-variant-numeric:tabular-nums}
.bench .bu{color:var(--muted);font-size:11px}
.bench .bc{margin-left:auto;font-size:11.5px;font-weight:600}
.up{color:var(--green)}
.down{color:var(--red)}
.flat{color:var(--muted)}
.tiles{flex:1;display:grid;grid-template-columns:repeat(var(--cols),1fr);gap:8px;min-height:0}
.tile{position:relative;display:flex;flex-direction:column;padding:10px 12px 8px;border:1px solid var(--border);border-radius:10px;cursor:pointer;overflow:hidden;min-width:0}
.tile:hover{background:var(--hover)}
.tile.selected{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent);background:var(--hover)}
.tile.ref:after{content:"REF";position:absolute;right:10px;top:10px;font-size:9.5px;font-weight:700;color:var(--muted);letter-spacing:.05em}
.hub{color:var(--muted);font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-right:26px}
.price{display:flex;align-items:baseline;gap:6px}
.price b{font-size:22px;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.chg{font-size:11.5px;font-weight:600;padding:0 6px;border-radius:9px}
.chg.up{background:color-mix(in srgb,var(--green) 14%,transparent)}
.chg.down{background:color-mix(in srgb,var(--red) 14%,transparent)}
.spark{flex:1;min-height:22px;margin:4px 0 2px}
.spark svg{display:block;width:100%;height:100%}
.basis{display:flex;justify-content:space-between;font-size:11px;color:var(--muted)}
.basis b{font-weight:600;font-variant-numeric:tabular-nums}
.foot{display:flex;justify-content:space-between;font-size:11px;color:var(--muted)}
.empty{grid-column:1/-1;color:var(--muted);text-align:center;padding:30px 0}

