function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const cls = v => v > 0 ? 'up' : v < 0 ? 'down' : 'flat';
  const sign = (v, d) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(d);
  const arrow = v => v > 0 ? '▲' : v < 0 ? '▼' : '■';

  // benchmarks strip
  const strip = root.querySelector('.strip');
  const bench = props.benchmarks || [];
  strip.style.display = props.showBenchmarks === false || !bench.length ? 'none' : '';
  strip.innerHTML = bench.map(b => {
    const c = +b.change || 0, d = +b.decimals >= 0 ? +b.decimals : 4;
    return '<div class="bench"><span class="bn">' + esc(b.name) + '</span><span class="bp">' + (+b.price || 0).toFixed(d) + '</span><span class="bu">' + esc(b.unit) + '</span>' +
      '<span class="bc ' + cls(c) + '">' + arrow(c) + ' ' + Math.abs(c).toFixed(d) + '</span></div>';
  }).join('');

  // hub tiles
  const tiles = root.querySelector('.tiles');
  const hubs = props.hubs || [];
  tiles.style.setProperty('--cols', Math.max(1, props.columns || 3));
  if (!hubs.length) { tiles.innerHTML = '<div class="empty">No prices</div>'; return; }
  const ref = hubs.find(h => h.id === props.referenceHub) || hubs[0];
  tiles.innerHTML = hubs.map(h => {
    const p = +h.price || 0, c = +h.change || 0, hist = (h.history || []).map(Number).filter(v => !isNaN(v));
    const basis = p - (+ref.price || 0), isRef = h.id === ref.id;
    let spark = '';
    if (hist.length > 1) {
      const lo = Math.min.apply(null, hist), hi = Math.max.apply(null, hist), W = 100, H = 30, r = hi - lo || 1;
      const pts = hist.map((v, i) => (i / (hist.length - 1) * W).toFixed(1) + ',' + (H - 2 - (v - lo) / r * (H - 4)).toFixed(1)).join(' ');
      const col = hist[hist.length - 1] >= hist[0] ? 'var(--green)' : 'var(--red)';
      spark = '<svg viewBox="0 0 100 30" preserveAspectRatio="none"><polyline points="' + pts + '" fill="none" stroke="' + col + '" stroke-width="1.6" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>';
    }
    return '<div class="tile' + (h.id === props.selected ? ' selected' : '') + (isRef && props.showBasis !== false ? ' ref' : '') + '" data-id="' + esc(h.id) + '">' +
      '<div class="hub">' + esc(h.hub) + '</div>' +
      '<div class="price"><b>$' + p.toFixed(4) + '</b><span class="chg ' + cls(c) + '">' + arrow(c) + ' ' + Math.abs(c).toFixed(4) + '</span></div>' +
      '<div class="spark">' + spark + '</div>' +
      (props.showBasis === false ? '' : '<div class="basis"><span>Basis to ' + esc(ref.hub.split(' ')[0]) + '</span><b class="' + (isRef ? 'flat' : cls(basis)) + '">' + (isRef ? '—' : sign(basis, 4)) + '</b></div>') +
      '</div>';
  }).join('');
  tiles.querySelectorAll('.tile').forEach(el => el.onclick = () => fire('hubSelected', { id: el.dataset.id, selected: el.dataset.id }));

  root.querySelector('.foot').innerHTML = '<span>Spot, $/gal · 10-day trend</span><span>' + esc(props.asOf || '') + '</span>';
}
